/**
 * Stores a new active template of the cooperative with the uploaded workbook as its version 1, either a free
 * template (no `slot`) or the template of the tax report slot (`slot` given). A template is data: placeholders
 * `${...}` are filled and one row per sheet may repeat; no formula and no code of a template is ever run.
 * Surrounding spaces of `name` and `description` are removed; an empty `description` is none.
 *
 * Refusals (nothing is stored):
 *
 * - 400 `VALIDATION_FAILED`: `name` missing, blank or over 200 characters, `description` over 500 characters,
 *   `file` missing (`errors[{field}]`); an unknown `slot` is 400 `MALFORMED_REQUEST`;
 * - 422 `TEMPLATE_TOO_LARGE`: the file is over 2 MB (2 097 152 bytes), checked before the file is read; a
 *   request over the upload limit of 10 MB is 413 `FILE_TOO_LARGE`;
 * - 400 `TEMPLATE_INVALID`: the file is not a usable template, with one `errors[{field: file, code}]` naming why:
 *   - `NOT_XLSX`: the name does not end in `.xlsx`, the content does not start with the zip signature, or the
 *     archive is not an Excel workbook (`.xlsm`, `.xls` and any other file are refused);
 *   - `MACROS`: a macro-enabled workbook content type or a `vbaProject.bin` part;
 *   - `ACTIVE_CONTENT`: ActiveX controls or embedded OLE objects;
 *   - `BROKEN_ZIP`: the archive or one of its parts is damaged or encrypted, or a part is not well-formed XML or
 *     declares a document type;
 *   - `UNPACKED_TOO_LARGE`: too many parts, too large when unpacked or compressed too highly (a compressed bomb),
 *     with the limits of the Excel import;
 *   - `TWO_ROW_SETS`: a sheet has more than one repeating row, or one row mixes placeholders of two row sets;
 * - 409 `TEMPLATE_NAME_TAKEN` (`errors[{field: name}]`): another active template of the cooperative has the name,
 *   ignoring case;
 * - 409 `TEMPLATE_SLOT_TAKEN` (`errors[{field: slot}]`): an active template is in the slot already; upload a
 *   new version of it instead (an archived template frees its slot and its name).
 *
 * Links to other workbooks and data connections are removed from the stored file and listed in `warnings`
 * (`EXTERNAL_LINKS_REMOVED`). `fileName` of the version is the base name of the uploaded file, sanitised;
 * `sha256` and `sizeBytes` are those of the stored file. Written to the audit log as
 * `REPORT_TEMPLATE_UPLOADED` (entity type `REPORT_TEMPLATE`, label the name, fields the version number and file
 * name). Requires `REPORT_TEMPLATES_MANAGE`; the platform operator has no cooperative data: 403.
 * @summary Upload a new template as its version 1
 */
export const uploadReportTemplate = async (uploadReportTemplateBody: UploadReportTemplateBody, options?: Parameters<typeof nadelFetch>[1]): Promise<ReportTemplateUploadResult> => {
    const formData = new FormData();
formData.append(`file`, uploadReportTemplateBody.file);
formData.append(`name`, uploadReportTemplateBody.name);
if(uploadReportTemplateBody.description !== undefined) {
 formData.append(`description`, uploadReportTemplateBody.description);
 }
if(uploadReportTemplateBody.slot !== undefined) {
 formData.append(`slot`, uploadReportTemplateBody.slot);
 }

  return nadelFetch<ReportTemplateUploadResult>(getUploadReportTemplateUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





